using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Creezio.Switcher;

internal static class CloudMissionQueueTests
{
    private static int Main(string[] args)
    {
        int count=0;try{RunAll((name,test)=>{test();count++;Console.WriteLine("PASS "+name);},args.Length==0?Path.Combine(Environment.CurrentDirectory,"work","queue-test-sandbox"):args[0]);Console.WriteLine("Cloud mission queue: "+count+" passed");return 0;}catch(Exception error){Console.WriteLine("FAIL "+error);return 1;}
    }
    private const string Secret="QUEUE_PRIVATE_PROMPT_MUST_REMAIN_ENCRYPTED";
    private static void Assert(bool condition,string reason){if(!condition)throw new Exception(reason);}
    private static Exception Reject(Action action){try{action();}catch(InvalidOperationException error){return error;}throw new Exception("Expected queue rejection");}
    private sealed class Fixture
    {
        internal readonly RelayStore Store;
        internal readonly RelaySession Source;
        internal CloudMissionQueue Queue;
        internal CloudQueueTeam Team;
        internal DateTime Now=new DateTime(2026,10,17,12,0,0,DateTimeKind.Utc);
        internal readonly List<CloudJob> Jobs=new List<CloudJob>();
        internal readonly List<CloudJobSpec> Requests=new List<CloudJobSpec>();
        internal readonly HashSet<string> InvalidTargets=new HashSet<string>();
        internal bool ThrowAfterSave,ThrowBeforeSave,ReserveOnly;
        internal bool CorruptCancellation,ThrowAfterCancellation;
        internal int CancelCalls;
        internal Action BeforeSubmit;
        internal Action<CloudQueueTarget> BindingCheck;
        internal int Lot;
        internal Fixture(string root,string name)
        {
            Store=new RelayStore(Path.Combine(root,"cloud-mission-queue",name));string home=Path.Combine(Store.Root,"orchestrator");Directory.CreateDirectory(home);
            Source=new RelaySession{Channel="orchestrator",Thread="source-chat",Account="source-account",Home=home,Token="PRIVATE_SESSION_TOKEN",Expires="private-expiry",RuntimeId="private-runtime"};
            Store.WriteRecord("channels.dpapi",new List<RelayChannel>{new RelayChannel{Id=Source.Channel,AccountKey=Source.Account,Home=home,Enabled=true}});
            Queue=NewQueue();Team=new CloudQueueTeam{Id="fixture-team",Name="Fixture team",Repository="owner/repo",ExplicitDelegation=true,Mandate="Run these prepared fixture missions",Enabled=true,MaximumParallel=2,Targets=new List<CloudQueueTarget>{Target('a'),Target('b')}};
            Queue.ConfigureTeam(Team,Source);
        }
        internal static CloudQueueTarget Target(char c){return new CloudQueueTarget{InstanceId=new String(c,32),ExpectedAccountKey="account-"+c,ConfigurationId="config-"+c,ConfigurationName="Environment "+c};}
        internal CloudMissionQueue NewQueue()
        {return new CloudMissionQueue(Store,()=>Jobs.Select(Clone).ToArray(),Submit,target=>{if(BindingCheck!=null)BindingCheck(target);if(InvalidTargets.Contains(target.InstanceId))throw new InvalidOperationException("PRIVATE_BINDING_DETAIL");},()=>Now,CancelBeforeSend);}
        private static T Clone<T>(T value){return Json.Read<T>(Json.Write(value));}
        private CloudJob CancelBeforeSend(string id)
        {
            CancelCalls++;var job=Jobs.Single(j=>j.Id==id);Assert(job.State=="attention"&&String.IsNullOrEmpty(job.ThreadId)&&String.IsNullOrEmpty(job.TurnId)&&String.IsNullOrEmpty(job.ExecutionSetupThreadId),"cancellation called for a possibly-started task");
            // Prove the native callback runs outside the queue lease.
            Queue.List(Source);job.State="cancelled";if(CorruptCancellation)job.AccountKey="wrong-cancellation-account";if(ThrowAfterCancellation)throw new IOException("PRIVATE_CANCELLATION_DIAGNOSTIC");return Clone(job);
        }
        private Task<CloudJob> Submit(CloudJobSpec request,RelaySession source,CancellationToken token)
        {
            if(BeforeSubmit!=null)BeforeSubmit();Requests.Add(Clone(request));Assert(source.Token==null&&source.Expires==null&&source.RuntimeId==null,"session secret survived scheduling");
            var durable=Queue.List(Source).Missions.Single(m=>m.Id==request.Id);Assert(durable.Request!=null&&durable.Target!=null&&new[]{"claimed","uncertain"}.Contains(durable.State),"side effect preceded durable claim");
            if(ThrowBeforeSave)throw new IOException(Secret);var prior=Jobs.SingleOrDefault(j=>j.Id==request.Id);if(prior!=null){if(prior.State=="reserved"){prior.State="queued";prior.Prompt=request.Prompt;}return Task.FromResult(Clone(prior));}
            var job=new CloudJob{SchemaVersion=2,Id=request.Id,InstanceId=request.Instance,AccountKey=request.ExpectedAccountKey,ConfigurationId=request.ConfigurationId,ConfigurationVersion="config-version",ConfigurationReadyVersion="ready-version",Branch="codex/fixture/"+request.Id,RepositoryIds=new[]{"native-repo-id"},Title=request.Title,Prompt=request.Prompt,Feature=request.Feature,Lot=request.Lot,Specification=request.Specification,Repository=request.Repository,Model=request.Model,ReasoningEffort=request.ReasoningEffort,PermissionProfile=request.PermissionProfile,Fingerprint=CloudMissionQueue.RequestFingerprint(request),State="queued",SourceChannel=source.Channel,SourceThread=source.Thread,SourceAccount=source.Account,SourceHome=source.Home};Jobs.Add(job);if(ReserveOnly){job.State="reserved";job.Prompt=null;throw new IOException(Secret);}if(ThrowAfterSave)throw new IOException(Secret);return Task.FromResult(Clone(job));
        }
        internal CloudPreparedMission Mission(string file=null,int priority=0)
        {
            string id=Guid.NewGuid().ToString("N");return new CloudPreparedMission{Id=id,TeamId=Team.Id,Title="Fixture mission",Prompt=Secret,Repository=Team.Repository,Feature="fixture-feature",Lot=(++Lot).ToString(),Specification="issue/fixture",ExplicitDelegation=true,Priority=priority,Model="gpt-6.1-sol",ReasoningEffort="ultra",PermissionProfile=":danger-full-access",ReservedFiles=new List<string>{file??"src/"+id+".cs"},EligibleInstanceIds=Team.Targets.Select(t=>t.InstanceId).ToList()};
        }
        internal CloudPreparedMission Prepare(string file=null,int priority=0){return Queue.Prepare(Mission(file,priority),Source);}
        internal CloudJob Legacy(char account='b',int ageMinutes=30)
        {
            var mission=Mission();var target=Target(account);var request=new CloudJobSpec{Id=mission.Id,Instance=target.InstanceId,ExpectedAccountKey=target.ExpectedAccountKey,ConfigurationId=target.ConfigurationId,Title=mission.Title,Prompt=mission.Prompt,Feature=mission.Feature,Lot=mission.Lot,Specification=mission.Specification,Repository=mission.Repository,Model=mission.Model,ReasoningEffort=mission.ReasoningEffort,PermissionProfile=mission.PermissionProfile,ExplicitDelegation=true,ReturnToSource=true};
            var job=new CloudJob{SchemaVersion=2,Id=request.Id,InstanceId=request.Instance,AccountKey=request.ExpectedAccountKey,ConfigurationId=request.ConfigurationId,ConfigurationVersion="config-version",ConfigurationReadyVersion="ready-version",RepositoryIds=new[]{"native-repo-id"},Title=request.Title,Prompt=request.Prompt,Feature=request.Feature,Lot=request.Lot,Specification=request.Specification,Repository=request.Repository,Model=request.Model,ReasoningEffort=request.ReasoningEffort,PermissionProfile=request.PermissionProfile,ReturnToSource=true,Branch="codex/fixture/legacy-"+request.Id,Fingerprint=CloudMissionQueue.RequestFingerprint(request),State="queued",SourceChannel=Source.Channel,SourceThread=Source.Thread,SourceAccount=Source.Account,SourceHome=Source.Home,CreatedUtc=Now.AddMinutes(-ageMinutes).ToString("o"),UpdatedUtc=Now.AddMinutes(-ageMinutes).ToString("o")};Jobs.Add(job);return job;
        }
        internal CloudQueueSnapshot Tick(int maximum=4){return Queue.Tick(CancellationToken.None,maximum).GetAwaiter().GetResult();}
        internal CloudJob Complete(string id,string state="completed")
        {var job=Jobs.Single(j=>j.Id==id);job.State=state;job.ThreadId="thread-"+id;job.TurnId="turn-"+id;job.ObservedExecution=new CloudTaskExecutionObservation{Model=job.Model,ReasoningEffort=job.ReasoningEffort,PermissionProfile=job.PermissionProfile,Verified=true};return job;}
        internal CloudPreparedMission Accept(CloudJob job){return Queue.Accept(job.Id,job.Id,job.ThreadId,job.TurnId,Source);}
        internal CloudJob FollowUp(CloudJob parent)
        {
            var child=Clone(parent);child.Id=Guid.NewGuid().ToString("N");child.SchemaVersion=3;child.Kind="follow-up";child.ParentId=parent.Id;child.RootJobId=parent.RootJobId??parent.Id;child.ParentTurnId=parent.TurnId;child.FollowUpNumber=(parent.FollowUpNumber??0)+1;child.Title="Correction fixture";child.Prompt="Correct the same PR within its scope";child.TurnId=null;child.ObservedExecution=null;child.State="queued";child.Fingerprint=CloudMissionQueue.FollowUpFingerprint(child,parent);Jobs.Add(child);return child;
        }
        internal CloudJob CompleteFollowUp(CloudJob child,string state="completed")
        {child.State=state;child.TurnId="turn-"+child.Id;child.ObservedExecution=new CloudTaskExecutionObservation{Model=child.Model,ReasoningEffort=child.ReasoningEffort,PermissionProfile=child.PermissionProfile,Verified=true};return child;}
    }
    internal static void RunAll(Action<string,Action> check,string root)
    {
        check("queue reads tolerate a short concurrent registry writer",()=>{
            var f=new Fixture(root,"read-contention");f.Prepare("docs/fixture.txt");Task<CloudQueueSnapshot> reading;
            using(var started=new ManualResetEventSlim()){
                using(f.Store.Lease("cloud-prepared-queue-v1")){
                    reading=Task.Run(()=>{started.Set();return f.Queue.List();});
                    if(!started.Wait(TimeSpan.FromSeconds(5)))throw new Exception("Reader did not start");
                    Thread.Sleep(700);
                }
                Assert(reading.GetAwaiter().GetResult().Missions.Count==1,"A short writer interrupted a passive queue read");
            }
        });
        check("queue preparation encrypts prompt and strips every session secret",()=>{
            var f=new Fixture(root,"encryption");var mission=f.Prepare();var persisted=f.NewQueue().List(f.Source).Missions.Single();Assert(persisted.Prompt==Secret,"lost prompt");Assert(persisted.Source.Token==null&&persisted.Source.RuntimeId==null&&persisted.Source.Expires==null,"persisted session token");
            foreach(string path in Directory.GetFiles(f.Store.Root,"cloud-prepared-*.dpapi")){string bytes=Encoding.UTF8.GetString(File.ReadAllBytes(path));Assert(!bytes.Contains(Secret)&&!bytes.Contains("PRIVATE_SESSION_TOKEN"),"plaintext sidecar");}Assert(mission.Model=="gpt-6.1-sol"&&mission.State=="queued","missing frozen settings");
        });
        check("queue refuses missing authorization source or execution defaults",()=>{
            var f=new Fixture(root,"authorization");var m=f.Mission();m.ExplicitDelegation=false;Reject(()=>f.Queue.Prepare(m,f.Source));m=f.Mission();m.Model=null;m.ReasoningEffort=null;m.PermissionProfile=null;Reject(()=>f.Queue.Prepare(m,f.Source));Reject(()=>f.Queue.ConfigureTeam(f.Team,null));var other=Json.Read<RelaySession>(Json.Write(f.Source));other.Thread="foreign-chat";Reject(()=>f.Queue.Prepare(f.Mission(),other));
        });
        check("queue replay preserves frozen preferences and rejects mandate replacement",()=>{
            var f=new Fixture(root,"immutable");CloudMissionPreferences.Save(f.Store,new CloudTaskExecutionOptions{Model="gpt-6.1-sol",ReasoningEffort="ultra",PermissionProfile=":danger-full-access"});var input=f.Mission();input.Model=null;input.ReasoningEffort=null;input.PermissionProfile=null;var original=f.Queue.Prepare(input,f.Source);
            CloudMissionPreferences.Save(f.Store,new CloudTaskExecutionOptions{Model="other-model",ReasoningEffort="low",PermissionProfile=":read-only"});Assert(f.NewQueue().Prepare(input,f.Source).Model==original.Model,"replay reread defaults");input.Prompt="different mandate";Reject(()=>f.Queue.Prepare(input,f.Source));
        });
        check("queue dependency graph rejects self missing foreign and persisted cycles",()=>{
            var f=new Fixture(root,"dag");var self=f.Mission();self.Dependencies.Add(new CloudQueueDependency{MissionId=self.Id});Reject(()=>f.Queue.Prepare(self,f.Source));var missing=f.Mission();missing.Dependencies.Add(new CloudQueueDependency{MissionId=Guid.NewGuid().ToString("N")});Reject(()=>f.Queue.Prepare(missing,f.Source));
            var first=f.Prepare();var second=f.Mission();second.Dependencies.Add(new CloudQueueDependency{MissionId=first.Id});var prepared=f.Queue.Prepare(second,f.Source);first.Dependencies.Add(new CloudQueueDependency{MissionId=prepared.Id,Mode="accepted"});f.Store.WriteRecord("cloud-prepared-mission-"+first.Id+".dpapi",first);Reject(()=>f.Tick());Assert(f.Requests.Count==0,"sent cyclic graph");
        });
        check("queue reservations reject traversal rooted wildcard and Windows aliases",()=>{
            var f=new Fixture(root,"paths");foreach(string path in new[]{"../secret","src/../secret","C:/temp","/tmp/x","\\server\\x","src//a","src/./a","src/*.cs","src/a ","src/a."}){var m=f.Mission(path);Reject(()=>f.Queue.Prepare(m,f.Source));}Assert(CloudMissionQueue.Overlap("src","SRC/a.cs")&&!CloudMissionQueue.Overlap("src/a","src/ab"),"directory boundary overlap incorrect");
        });
        check("queue priority then FIFO selects meaningful missions without duplicate account",()=>{
            var f=new Fixture(root,"priority");var low=f.Prepare(null,1);f.Now=f.Now.AddSeconds(1);var high=f.Prepare(null,10);f.Now=f.Now.AddSeconds(1);var next=f.Prepare(null,10);f.Tick();Assert(f.Requests.Count==2&&f.Requests[0].Id==high.Id&&f.Requests[1].Id==next.Id,"priority/FIFO changed");Assert(f.Requests.Select(r=>r.ExpectedAccountKey).Distinct().Count()==2,"same-account parallel admission");Assert(f.Queue.List().Missions.Single(m=>m.Id==low.Id).State=="queued","global capacity exceeded");
        });
        check("queue global team and account limits include direct queued jobs",()=>{
            var f=new Fixture(root,"capacity");f.Team.MaximumParallel=1;f.Queue.ConfigureTeam(f.Team,f.Source);f.Prepare();f.Prepare();f.Tick();Assert(f.Requests.Count==1,"team cap bypass");
            var g=new Fixture(root,"external-account");g.Jobs.Add(new CloudJob{Id=Guid.NewGuid().ToString("N"),State="queued",AccountKey="account-a",Repository="other/repo"});g.Prepare();g.Tick();Assert(g.Requests.Count==1&&g.Requests[0].ExpectedAccountKey=="account-b","direct backlog did not consume its account");
        });
        check("queue directory reservations hold through completed pending review",()=>{
            var f=new Fixture(root,"files");var first=f.Prepare("src");var second=f.Prepare("src/nested/file.cs");f.Tick();Assert(f.Requests.Count==1,"overlapping files dispatched");var job=f.Complete(first.Id);f.Tick();Assert(f.Requests.Count==1&&f.Queue.List().Missions.Single(m=>m.Id==second.Id).BlockReason=="files-reserved","completed result released files before review");f.Accept(job);f.Tick();Assert(f.Requests.Count==2,"acceptance did not release reservation");
        });
        check("queue default dependencies await exact review acceptance",()=>{
            var f=new Fixture(root,"acceptance");var first=f.Prepare();var second=f.Mission();second.Dependencies.Add(new CloudQueueDependency{MissionId=first.Id});f.Queue.Prepare(second,f.Source);f.Tick();var job=f.Complete(first.Id);f.Tick();Assert(f.Requests.Count==1,"completion bypassed default review");Reject(()=>f.Queue.Accept(first.Id,first.Id,"wrong-thread",job.TurnId,f.Source));job.ObservedExecution.Verified=false;Reject(()=>f.Accept(job));job.ObservedExecution.Verified=true;f.Accept(job);f.Accept(job);f.Tick();Assert(f.Requests.Count==2,"accepted dependency stayed blocked");
        });
        check("queue explicit completed dependencies never accept failed or uncertain results",()=>{
            var f=new Fixture(root,"completed-mode");var first=f.Prepare();var second=f.Mission();second.Dependencies.Add(new CloudQueueDependency{MissionId=first.Id,Mode="completed"});f.Queue.Prepare(second,f.Source);f.Tick();f.Complete(first.Id);f.Tick();Assert(f.Requests.Count==2,"explicit completed dependency ignored");
            var g=new Fixture(root,"failed-mode");var parent=g.Prepare();var child=g.Mission();child.Dependencies.Add(new CloudQueueDependency{MissionId=parent.Id,Mode="completed"});g.Queue.Prepare(child,g.Source);g.Tick();g.Complete(parent.Id,"failed");g.Tick();Assert(g.Requests.Count==1,"failed dependency treated as success");
        });
        check("queue frozen account targets cannot be revoked silently or repinned after claim",()=>{
            var f=new Fixture(root,"revocation");var prepared=f.Prepare();f.Team.Targets.RemoveAt(1);f.Queue.ConfigureTeam(f.Team,f.Source);f.InvalidTargets.Add(Fixture.Target('a').InstanceId);f.Tick();Assert(f.Requests.Count==0,"removed eligible target reused");Assert(f.Queue.List().Missions.Single().BlockReason=="target-unavailable","unavailable binding falsely ready");Assert(prepared.EligibleTargets.Count==2,"preparation did not snapshot candidates");
            var g=new Fixture(root,"pinning");g.ThrowBeforeSave=true;g.Prepare();g.Tick();string pinned=g.Queue.List().Missions.Single().Target.InstanceId;g.Team.Targets.RemoveAll(t=>t.InstanceId==pinned);g.Queue.ConfigureTeam(g.Team,g.Source);g.Now=g.Now.AddMinutes(1);g.Tick();Assert(g.Requests.Count==1&&g.Queue.List().Missions.Single().Target.InstanceId==pinned,"uncertain request repinned");
        });
        check("queue retries uncertain materialization with same durable id and request",()=>{
            var f=new Fixture(root,"uncertain");f.ThrowBeforeSave=true;var prepared=f.Prepare();f.Tick();var first=Json.Write(f.Requests.Single());var state=f.NewQueue().List().Missions.Single();Assert(state.State=="uncertain"&&!Json.Write(state).Contains("PRIVATE_BINDING_DETAIL"),"unsafe failure state");f.Tick();Assert(f.Requests.Count==1,"retry ignored backoff");f.Now=f.Now.AddMinutes(1);f.ThrowBeforeSave=false;f.Queue=f.NewQueue();f.Tick();Assert(f.Requests.Count==2&&Json.Write(f.Requests[1])==first&&f.Jobs.Count==1&&f.Jobs[0].Id==prepared.Id,"crash recovery changed request");
        });
        check("queue discovers submitted job after lost acknowledgement without resubmission",()=>{
            var f=new Fixture(root,"lost-reply");f.ThrowAfterSave=true;f.Prepare();f.Tick();f.Queue=f.NewQueue();f.Now=f.Now.AddMinutes(2);f.Tick();Assert(f.Requests.Count==1&&f.Jobs.Count==1&&f.Queue.List().Missions.Single().State=="submitted","replayed acknowledged native job");
        });
        check("queue concurrent workers cannot submit the same claimed request twice",()=>{
            var f=new Fixture(root,"concurrent");f.Prepare();using(var entered=new ManualResetEvent(false))using(var release=new ManualResetEvent(false)){
                f.BeforeSubmit=()=>{entered.Set();Assert(release.WaitOne(5000),"submission fixture release timed out");};
                var first=Task.Factory.StartNew(()=>f.Tick());Assert(entered.WaitOne(5000),"first worker did not claim");try{f.NewQueue().Tick(CancellationToken.None).GetAwaiter().GetResult();}finally{release.Set();}first.GetAwaiter().GetResult();Assert(f.Requests.Count==1&&f.Jobs.Count==1,"concurrent claim replayed side effect");
            }
        });
        check("queue observed wrong account thread or fingerprint never releases dependent work",()=>{
            var f=new Fixture(root,"wrong-observation");var first=f.Prepare();var second=f.Mission();second.Dependencies.Add(new CloudQueueDependency{MissionId=first.Id,Mode="completed"});f.Queue.Prepare(second,f.Source);f.Tick();var job=f.Complete(first.Id);job.AccountKey="wrong-account";f.Tick();Assert(f.Requests.Count==1&&f.Queue.List().Missions.Single(m=>m.Id==first.Id).ErrorCode=="observed-job-mismatch","wrong account accepted");Reject(()=>f.Accept(job));
        });
        check("queue completed results require verified frozen native execution",()=>{
            var f=new Fixture(root,"unverified-execution");var first=f.Prepare();f.Tick();var job=f.Complete(first.Id);job.ObservedExecution.ReasoningEffort="low";f.Tick();Assert(f.Queue.List().Missions.Single().State=="uncertain","unverified completion considered safe");Reject(()=>f.Accept(job));
        });
        check("queue pause drain cancel and team edits preserve operator control",()=>{
            var f=new Fixture(root,"pauses");var prepared=f.Prepare();f.Queue.SetTeamPaused(f.Team.Id,true,f.Source);f.Team.Name="Renamed";Assert(f.Queue.ConfigureTeam(f.Team,f.Source).Paused,"rename cleared pause");f.Tick();Assert(f.Requests.Count==0,"paused team admitted");f.Queue.SetTeamPaused(f.Team.Id,false,f.Source);RelayDispatch.Set(f.Store,"drain");f.Tick();Assert(f.Requests.Count==0&&!CloudMissionQueue.HasReadyAdmissions(f.Queue.List()),"drain admitted prepared mission");RelayDispatch.Set(f.Store,"running");f.Queue.SetMissionPaused(prepared.Id,true,f.Source);f.Tick();Assert(f.Requests.Count==0,"mission pause ignored");f.Queue.Cancel(prepared.Id,f.Source);f.Queue.Cancel(prepared.Id,f.Source);f.Tick();Assert(f.Requests.Count==0,"cancelled mission admitted");
        });
        check("queue reject releases failed files but never satisfies a dependency",()=>{
            var f=new Fixture(root,"reject");var parent=f.Prepare("src");var independent=f.Prepare("src/a.cs");var child=f.Mission("other/file");child.Dependencies.Add(new CloudQueueDependency{MissionId=parent.Id});f.Queue.Prepare(child,f.Source);f.Tick();var job=f.Complete(parent.Id,"failed");f.Tick();Assert(f.Requests.Count==1,"failed reservation released without review");var rejected=f.Queue.Reject(parent.Id,parent.Id,job.ThreadId,job.TurnId,f.Source);Assert(rejected.State=="rejected","missing rejected state");f.Tick();Assert(f.Requests.Count==2&&f.Requests[1].Id==independent.Id,"reject did not release only independent work");Reject(()=>f.Accept(job));
        });
        check("queue rejects release of uncertain active or foreign jobs",()=>{
            var f=new Fixture(root,"unsafe-reject");var first=f.Prepare();f.Tick();var job=f.Complete(first.Id,"uncertain");Reject(()=>f.Queue.Reject(first.Id,first.Id,job.ThreadId,job.TurnId,f.Source));job.State="running";Reject(()=>f.Queue.Reject(first.Id,first.Id,job.ThreadId,job.TurnId,f.Source));job.State="failed";var foreign=Json.Read<RelaySession>(Json.Write(f.Source));foreign.Thread="foreign-chat";Reject(()=>f.Queue.Reject(first.Id,first.Id,job.ThreadId,job.TurnId,foreign));
        });
        check("queue unknown legacy file claims block conservatively only within repository",()=>{
            var f=new Fixture(root,"legacy");f.Prepare();f.Jobs.Add(new CloudJob{Id=Guid.NewGuid().ToString("N"),State="running",Repository="owner/repo",AccountKey="unrelated-account",ThreadId="legacy-thread"});f.Tick();Assert(f.Requests.Count==0&&f.Queue.List().Missions.Single().BlockReason=="legacy-files-unknown","legacy unknown scope did not block");f.Jobs[0].Repository="other/repo";f.Tick();Assert(f.Requests.Count==1,"unrelated repository blocked forever");
        });
        check("queue admission boundary blocks direct unknown writes without stopping running jobs",()=>{
            var f=new Fixture(root,"boundary");f.Prepare();f.Tick();var direct=new CloudJob{Id=Guid.NewGuid().ToString("N"),State="queued",Repository="owner/repo",AccountKey="account-x"};Assert(!f.Queue.AllowsJobStart(direct,f.Jobs.ToArray()),"direct write bypassed held files");direct.State="running";direct.TurnId="already-running";Assert(f.Queue.AllowsJobStart(direct,f.Jobs.ToArray()),"existing running user job interrupted");direct.State="queued";direct.TurnId=null;direct.Repository="other/repo";Assert(f.Queue.AllowsJobStart(direct,f.Jobs.ToArray()),"unrelated direct repo blocked");Assert(f.Queue.AllowsJobStart(f.Jobs.Single(),f.Jobs.ToArray()),"own exact managed job refused");
        });
        check("queue empty registered team raises once after five minutes across restart",()=>{
            var f=new Fixture(root,"idle");Assert(f.Tick(0).Alerts.Count==0,"early idle alert");f.Now=f.Now.AddMinutes(5);var first=f.Tick(0).Alerts.Single();Assert(first.Active&&first.Reason=="empty-backlog","empty registered team not monitored");f.Queue.MarkIdleNotified(f.Team.Id,first.EpisodeId);f.Queue.AcknowledgeIdle(f.Team.Id,first.EpisodeId,f.Source);f.Queue=f.NewQueue();f.Now=f.Now.AddMinutes(10);var repeated=f.Tick(0).Alerts.Single();Assert(repeated.EpisodeId==first.EpisodeId&&repeated.NotifiedUtc!=null&&repeated.AcknowledgedUtc!=null,"idle alert spam after restart");
        });
        check("queue idle recovers on confirmed execution and raises a fresh episode",()=>{
            var f=new Fixture(root,"idle-recovery");f.Tick(0);f.Now=f.Now.AddMinutes(6);var first=f.Tick(0).Alerts.Single();var prepared=f.Prepare();f.Tick();f.Complete(prepared.Id,"running");Assert(!f.Tick(0).Alerts.Single().Active,"confirmed work did not recover idle");var job=f.Complete(prepared.Id);f.Accept(job);f.Tick(0);f.Now=f.Now.AddMinutes(6);var second=f.Tick(0).Alerts.Single();Assert(second.Active&&second.EpisodeId!=first.EpisodeId,"recovery lost next idle episode");
        });
        check("queue unconfirmed submission raises intervention alert without claiming execution",()=>{
            var f=new Fixture(root,"idle-uncertain");f.ThrowBeforeSave=true;f.Prepare();f.Tick();f.Now=f.Now.AddMinutes(6);var alert=f.Tick(0).Alerts.Single();Assert(alert.Active&&alert.Reason=="execution-unconfirmed","uncertain claim suppressed idle indefinitely");
        });
        check("queue paused disabled and global drain teams do not raise idle alarms",()=>{
            var f=new Fixture(root,"idle-paused");f.Queue.SetTeamPaused(f.Team.Id,true,f.Source);f.Tick(0);f.Now=f.Now.AddMinutes(10);Assert(f.Tick(0).Alerts.Count==0,"paused team idle alarm");f.Queue.SetTeamPaused(f.Team.Id,false,f.Source);RelayDispatch.Set(f.Store,"paused");f.Tick(0);f.Now=f.Now.AddMinutes(10);Assert(f.Tick(0).Alerts.Count==0,"global pause idle alarm");
